use focusflow_windows_device_test::{analysis,format::{Encoding,Format},signal::Signal,selected_index};
use std::{fs,path::PathBuf,sync::atomic::{AtomicUsize,Ordering}};
static NEXT:AtomicUsize=AtomicUsize::new(0);
fn path()->PathBuf{std::env::temp_dir().join(format!("focusflow-device-content-{}-{}.wav",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)))}
fn fixture(seed:u32,swap:bool,break_middle:bool)->(PathBuf,u64){
 let p=path();let f=Format{rate:48000,channels:2,bits:16,valid_bits:16,align:4,encoding:Encoding::Pcm};
 let mut signal=Signal::new(f,seed).unwrap();let mut samples=vec![0i16;4800*2];
 while signal.remaining()>0{let bytes=signal.block(1024).unwrap();for frame in bytes.chunks_exact(4){let l=i16::from_le_bytes([frame[0],frame[1]])/2;let r=i16::from_le_bytes([frame[2],frame[3]])/2;samples.extend(if swap{[r,l]}else{[l,r]});}}
 samples.extend(vec![0i16;4800*2]);if break_middle{samples[4800*2+3*48000*2..4800*2+4*48000*2].fill(0);}
 let mut wav=hound::WavWriter::create(&p,hound::WavSpec{sample_rate:48000,channels:2,bits_per_sample:16,sample_format:hound::SampleFormat::Int}).unwrap();for sample in &samples{wav.write_sample(*sample).unwrap();}wav.finalize().unwrap();(p,(samples.len()/2)as u64)
}
#[test]fn content_signature_accepts_gain_and_diagnostic_offset(){let(p,n)=fixture(1,false,false);let r=analysis::inspect(&p,n);fs::remove_file(p).unwrap();let r=r.unwrap();assert_eq!(r.status,"Pass");assert_eq!(r.diagnostic_offset_frames,Some(4800));}
#[test]fn unrelated_signal_cannot_pass(){let(p,n)=fixture(0xdeadbeef,false,false);let r=analysis::inspect(&p,n);fs::remove_file(p).unwrap();assert!(!r.as_ref().is_ok_and(|a|a.status=="Pass"),"unrelated signal: {r:?}");}
#[test]fn swapped_channels_cannot_pass(){let(p,n)=fixture(1,true,false);let r=analysis::inspect(&p,n);fs::remove_file(p).unwrap();assert!(!r.as_ref().is_ok_and(|a|a.status=="Pass"),"swapped channels: {r:?}");}
#[test]fn missing_interior_burst_cannot_pass(){let(p,n)=fixture(1,false,true);let r=analysis::inspect(&p,n);fs::remove_file(p).unwrap();assert!(r.is_err()||r.unwrap().status!="Pass");}
#[test]fn independent_inventory_rejects_declared_count_mismatch(){let(p,n)=fixture(1,false,false);let r=analysis::inspect(&p,n+1);fs::remove_file(p).unwrap();assert!(r.is_err());}
#[test]fn malformed_and_empty_wav_fail(){let p=path();fs::write(&p,b"not a WAV").unwrap();assert!(analysis::inspect(&p,0).is_err());fs::remove_file(p).unwrap();}
#[test]fn reference_has_independent_literal_golden_channel_order(){let f=Format{rate:8000,channels:2,bits:16,valid_bits:16,align:4,encoding:Encoding::Pcm};let mut s=Signal::new(f,1).unwrap();for n in [1024,1024,352]{assert!(s.block(n).unwrap().iter().all(|b|*b==0));}let b=s.block(3).unwrap();let v:Vec<_>=b.chunks_exact(2).map(|x|i16::from_le_bytes([x[0],x[1]])).collect();assert_eq!(v,[-514,-6173,-4369,-2832,7196,1539]);}
#[test]fn selection_is_explicit_and_bounded(){for x in ["","0","3","-1","x"]{assert!(selected_index(x,2).is_err());}assert_eq!(selected_index(" 2 ",2).unwrap(),1);assert!(selected_index("1",0).is_err());}
#[test]fn malformed_worker_mode_never_enters_console(){assert_eq!(focusflow_windows_audio_worker::worker::dispatch(["--private-owned-audio-worker".into()].into_iter()),Some(64));}
#[test]fn unsupported_existing_rate_is_unavailable_not_pass(){let p=path();let mut w=hound::WavWriter::create(&p,hound::WavSpec{sample_rate:44100,channels:2,bits_per_sample:16,sample_format:hound::SampleFormat::Int}).unwrap();w.write_sample(0i16).unwrap();w.write_sample(0i16).unwrap();w.finalize().unwrap();let r=analysis::inspect(&p,1).unwrap();fs::remove_file(p).unwrap();assert_eq!(r.status,"Unavailable");}
#[test]fn header_and_file_size_must_match_worker_inventory(){let(p,n)=fixture(1,false,false);let mut inv=focusflow_windows_audio_worker::protocol::WavInventory{frames:n,rate:48000,channels:2,bits:16,encoding:Encoding::Pcm,file_bytes:fs::metadata(&p).unwrap().len()};inv.file_bytes+=1;assert!(analysis::inspect_inventory(&p,&inv).is_err());inv.file_bytes-=1;inv.rate=44100;assert!(analysis::inspect_inventory(&p,&inv).is_err());fs::remove_file(p).unwrap();}
#[test]fn silence_is_not_a_content_pass(){let p=path();let n=12*48000;let mut w=hound::WavWriter::create(&p,hound::WavSpec{sample_rate:48000,channels:2,bits_per_sample:16,sample_format:hound::SampleFormat::Int}).unwrap();for _ in 0..n*2{w.write_sample(0i16).unwrap();}w.finalize().unwrap();let r=analysis::inspect(&p,n);fs::remove_file(p).unwrap();assert!(!r.as_ref().is_ok_and(|a|a.status=="Pass"),"silence: {r:?}");}
#[test]fn float32_content_matches_and_nonfinite_samples_fail(){
 let(original,n)=fixture(1,false,false);let p=path();let mut r=hound::WavReader::open(&original).unwrap();let mut w=hound::WavWriter::create(&p,hound::WavSpec{sample_rate:48000,channels:2,bits_per_sample:32,sample_format:hound::SampleFormat::Float}).unwrap();for sample in r.samples::<i16>(){w.write_sample(f32::from(sample.unwrap())/32768.0).unwrap();}w.finalize().unwrap();let result=analysis::inspect(&p,n);fs::remove_file(&p).unwrap();fs::remove_file(original).unwrap();assert_eq!(result.unwrap().status,"Pass");
 let mut w=hound::WavWriter::create(&p,hound::WavSpec{sample_rate:48000,channels:2,bits_per_sample:32,sample_format:hound::SampleFormat::Float}).unwrap();for i in 0..n*2{w.write_sample(if i==0{f32::NAN}else{0.0}).unwrap();}w.finalize().unwrap();assert!(analysis::inspect(&p,n).is_err());fs::remove_file(p).unwrap();
}
#[test]fn reference_is_finite_and_never_overwrites_existing_file(){let p=path();focusflow_windows_device_test::write_reference(&p).unwrap();let r=hound::WavReader::open(&p).unwrap();assert_eq!(r.duration(),12*48000);assert_eq!(r.spec().channels,2);drop(r);assert!(focusflow_windows_device_test::write_reference(&p).is_err());fs::remove_file(p).unwrap();}
